import { NextRequest, NextResponse } from 'next/server';

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/db';

export async function GET(
  request: NextRequest,
  { params }: { params: { pdfId: string } }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { pdfId } = params;

    // Verify the PDF belongs to the user or is accessible
    const pdf = await prisma.pDF.findFirst({
      where: {
        id: pdfId,
        userId: session.user.id, // Ensure user owns the PDF
      },
      select: { id: true },
    });

    if (!pdf) {
      return NextResponse.json(
        { error: 'PDF not found or access denied' },
        { status: 404 }
      );
    }

    const flags = await prisma.flag.findMany({
      where: {
        pdfId: pdfId,
      },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
      orderBy: [
        { section: 'asc' },
        { startIndex: 'asc' },
        { createdAt: 'desc' },
      ],
    });

    // Get flag statistics
    const flagStats = await prisma.flag.groupBy({
      by: ['type', 'status'],
      where: {
        pdfId: pdfId,
      },
      _count: {
        id: true,
      },
    });

    const stats = flagStats.reduce((acc, stat) => {
      const key = `${stat.type}_${stat.status}`;
      acc[key] = stat._count.id;
      return acc;
    }, {} as Record<string, number>);

    return NextResponse.json({
      flags,
      stats,
      total: flags.length,
    });
  } catch (error) {
    console.error('Error fetching flags:', error);
    return NextResponse.json(
      { error: 'Failed to fetch flags' },
      { status: 500 }
    );
  }
}